-- Compara os mesmos registros e campos, mas devolve apenas 32 bytes por tabela.
-- CONVERT(varbinary(max)) preserva o XML completo, inclusive além de 8.000 bytes.
SELECT
 HASHBYTES('SHA2_256',CONVERT(varbinary(max),ISNULL((SELECT * FROM dbo.LMC WHERE ID_FILIAL<>@branch OR ID_LMC<>@id ORDER BY ID_FILIAL,ID_LMC FOR XML RAW,BINARY BASE64),N''))),
 HASHBYTES('SHA2_256',CONVERT(varbinary(max),ISNULL((SELECT * FROM dbo.LMCBICOS WHERE ID_FILIAL<>@branch OR ID_LMC<>@id ORDER BY ID_FILIAL,ID_LMCBICOS FOR XML RAW,BINARY BASE64),N''))),
 HASHBYTES('SHA2_256',CONVERT(varbinary(max),ISNULL((SELECT * FROM dbo.LMCTANQUES WHERE ID_FILIAL<>@branch OR ID_LMC<>@id ORDER BY ID_FILIAL,ID_LMCTANQUES FOR XML RAW,BINARY BASE64),N''))),
 HASHBYTES('SHA2_256',CONVERT(varbinary(max),ISNULL((SELECT * FROM dbo.LMCCOMPROVANTES WHERE ID_FILIAL<>@branch OR ID_LMC<>@id ORDER BY ID_FILIAL,ID_LMCCOMPROVANTES FOR XML RAW,BINARY BASE64),N''))),
 HASHBYTES('SHA2_256',CONVERT(varbinary(max),ISNULL((SELECT * FROM dbo.LEITURASTANQUES ORDER BY ID_FILIAL,ID_LEITURASTANQUES FOR XML RAW,BINARY BASE64),N''))),
 HASHBYTES('SHA2_256',CONVERT(varbinary(max),ISNULL((SELECT * FROM dbo.ESTOQUETANQUELMC ORDER BY ID_FILIAL,ID_ESTOQUETANQUESLMC FOR XML RAW,BINARY BASE64),N''))),
 HASHBYTES('SHA2_256',CONVERT(varbinary(max),ISNULL((SELECT * FROM dbo.MOVTANQUES ORDER BY ID_FILIAL,ID_DB,ID_MOVTANQUES FOR XML RAW,BINARY BASE64),N''))),
 HASHBYTES('SHA2_256',CONVERT(varbinary(max),ISNULL((SELECT * FROM dbo.QTDESTANQUES ORDER BY ID_FILIAL,ID_TANQUES FOR XML RAW,BINARY BASE64),N''))),
 HASHBYTES('SHA2_256',CONVERT(varbinary(max),ISNULL((SELECT * FROM dbo.CFGLMC ORDER BY ID_CFGLMC FOR XML RAW,BINARY BASE64),N''))),
 HASHBYTES('SHA2_256',CONVERT(varbinary(max),ISNULL((SELECT * FROM dbo.TURNOS ORDER BY ID_FILIAL,ID_TURNOS FOR XML RAW,BINARY BASE64),N''))),
 HASHBYTES('SHA2_256',CONVERT(varbinary(max),ISNULL((SELECT * FROM dbo.LMCENTRADATANQUES ORDER BY ID_FILIAL,ID_LMCENTRADATANQUES FOR XML RAW,BINARY BASE64),N''))),
 HASHBYTES('SHA2_256',CONVERT(varbinary(max),ISNULL((SELECT * FROM dbo.LMC_WS ORDER BY ID_FILIAL,ID_LMC_WS FOR XML RAW,BINARY BASE64),N''))),
 HASHBYTES('SHA2_256',CONVERT(varbinary(max),ISNULL((SELECT * FROM dbo.LMC_WS_VINCULADO ORDER BY ID_FILIAL,ID_LMC_WS_VINCULADO FOR XML RAW,BINARY BASE64),N'')));
